from pandas.errors import OutOfBoundsDatetime

# Example 1: Period('2300-01-01', freq='ns')
try:
    result = Period('2300-01-01', freq='ns')
    probe("Period('2300-01-01', freq='ns')", result)
except Exception as e:
    probe("Period('2300-01-01', freq='ns')", "__error__: " + type(e).__name__ + ": " + str(e))

