import pandas as pd
from pandas.errors import OutOfBoundsDatetime
import traceback

# Test 1: Period('2300-01-01', freq='ns') should return 1970 epoch on buggy
try:
    p = pd.Period('2300-01-01', freq='ns')
    probe('period_2300_ns_ordinal', p.ordinal)
    probe('period_2300_ns_value', p.value)
except OutOfBoundsDatetime as e:
    probe('period_2300_ns_error', 1.0)
except Exception as e:
    probe('period_2300_ns_other_error', float(str(type(e).__name__).count('Error')))

# Test 2: Period(year=300000, month=1, day=1, freq='us')
try:
    p = pd.Period(year=300000, month=1, day=1, freq='us')
    probe('period_year300000_us_ordinal', p.ordinal)
    probe('period_year300000_us_value', p.value)
except OutOfBoundsDatetime as e:
    probe('period_year300000_us_error', 1.0)
except Exception as e:
    probe('period_year300000_us_other_error', float(str(type(e).__name__).count('Error')))

