    p = pd.Period('1600-01-01', freq='ns')
    probe('period_1600_ns_ordinal', p.ordinal)
    probe('period_1600_ns_value', p.value)
except OutOfBoundsDatetime as e:
    probe('period_1600_ns_error', 1.0)
except Exception as e:
    probe('period_1600_ns_other_error', float(str(type(e).__name__).count('Error')))

# Test 4: PeriodIndex with out-of-bounds ordinal
try:
    pi = pd.PeriodIndex(['2000-01-01', '2300-01-01', '2001-01-01'], freq='ns')
    probe('periodindex_ordinals_0', float(pi.asi8[0]))
    probe('periodindex_ordinals_1', float(pi.asi8[1]))
    probe('periodindex_ordinals_2', float(pi.asi8[2]))
except OutOfBoundsDatetime as e:
    probe('periodindex_error', 1.0)
except Exception as e:
    probe('periodindex_other_error', float(str(type(e).__name__).count('Error')))

# Test 5: DatetimeIndex.to_period with ns frequency
try:
    dti = pd.date_range('2300-01-01', periods=2, freq='D')
    pi = dti.to_period('ns')
    probe('to_period_ns_0', float(pi[0].ordinal))
    probe('to_period_ns_1', float(pi[1].ordinal))
except OutOfBoundsDatetime as e:
    probe('to_period_ns_error', 1.0)
except Exception as e:
    probe('to_period_ns_other_error', float(str(type(e).__name__).count('Error')))

